const unlockUserAchievement = `-- name: UnlockUserAchievement :exec
INSERT INTO user_achievements (id_user, id_achievement, unlocked_at)
VALUES ($1, $2, now())
ON CONFLICT (id_user, id_achievement) DO NOTHING
`

type UnlockUserAchievementParams struct {
	IDUser        uuid.UUID `json:"id_user"`
	IDAchievement int32     `json:"id_achievement"`
}

// 12. Desbloquear Logro
